WITH latest AS (SELECT * FROM subscriptions QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY start_date DESC NULLS FIRST, id) = 1) SELECT s.id, s.customer_id, s.plan, s.monthly_fee, s.status, CASE WHEN status RLIKE '^(PAUSED|ACTIVE)$' THEN 'EXTENDED' ELSE 'GROUP_A' END AS status_zone, (SELECT MIN(x.shipping_fee) FROM orders x WHERE x.customer_id = s.customer_id) AS min_order_shipping_fee FROM latest s ORDER BY customer_id DESC NULLS LAST
